export type ILifecycleUnit<T> = {
  readonly state: IUnitState;
  /** * The container-survival axis for the unit itself (separate from `state`) — `close()`/`dispose()` * move this one. */ readonly lifecycle: ILifecycleState;
  readonly value: T | undefined;
