export type IReleaseContext = {
  /** Aborts when the owning transaction/scope enters `closing` (L-T26). */ readonly signal: IAbortSignal;
  readonly deadlineAt: number | undefined;
  /** * The scheduler whose `now()` produced `deadlineAt`（R-9 时间域契约）. Omitted → `systemScheduler`. * Exposed so descriptor callbacks and the graceful-phase deadline share one clock source instead * of silently mixing domains. */ readonly scheduler?: ILifecycleScheduler;
