export type IReleaseDescriptor = {
  /** * Declares this descriptor may be accepted by `SyncLifecycleScope`. Does not change the static * type of the general-purpose `LifecycleScope` (D-6) — a scope's sync/async nature is determined * by which concrete type you construct, never inferred from descriptor content. */ readonly syncSafe?: boolean;
  /** * Release ordering key. Higher values release first, lower values release last (lower "sinks to * the bottom" of the release order — the opposite of allocation order). Omitted keys are treated * as `0`. Only meaningful in `DisposeTransaction`'s `order` mode (D-3: this module never * computes order, it only executes an order supplied by the caller). */ readonly order?: number;
  /** * Graceful release. A timeout abandons waiting for it (does not cancel it) and falls through to * `force`. */ readonly graceful?: (
    context: IReleaseContext,
  ) => void | PromiseLike<void>;
  /** Budget for the graceful phase, capped by the transaction's shared `deadlineAt` if one exists. */ readonly gracefulTimeoutMs?: number;
  /** Forced release. Must complete unconditionally; must not throw a recoverable error. */ readonly force: (
    context: IReleaseContext,
  ) => void | PromiseLike<void>;
  /** * GC fallback. When set, the core registers a `FinalizationRegistry` entry that unregisters on * explicit release. */ readonly gcFallback?: boolean;
  /** * Escape hatch: fully takes over this resource's release. The core only orders and collects * errors. */ readonly custom?: (
    context: IReleaseContext,
  ) => void | PromiseLike<void>;
};

