export type ILoggerOptions<
  P extends readonly ILoggerPluginConstraint[] = [],
  TMode extends IPipelineMode = 'sync',
> = {
  /** Explicit PluginHost operation and drain budgets; `false` opts into unbounded waiting. */ execution: IPluginHostOptions['execution'];
  context?: string[];
  /** 这个 logger 自己的 topic，用于 extends() 组合时展示 `[topic1 -> topic2]` 链路 */ topic?: string;
  /** 构造时直接注册钩子的语法糖，等价于逐个调用 core.hook(name, fn) */ on?: Record<
    string,
    ILogHookFn
  >;
  plugins?: P;
  /** * 业务自定义配置，会原样出现在每个插件都能读到的 core.ctx.options 里 （不包含 context/on/plugins 这些框架内部字段——那几个有各自的用途， * 不适合和"业务自定义配置"混在一起暴露给插件）。 */ options?: Record<
    string,
    unknown
  >;
  pipeline?: IPluginHostOptions['pipeline'] & { mode?: TMode };
  /** 缺省 lifecycle `systemScheduler`；`flush`/`shutdown`/`batch` 的 deadline 均用它（R-9 时间域）。 */ scheduler?: ILifecycleScheduler;
};

export type ILoggerPluginConfig = {
  get<T extends IPluginConfig = IPluginConfig>(): Readonly<T>;
};

export type ILoggerPluginCore<
  TMode extends IPipelineConfig['mode'] = IPipelineMode,
  TShared extends Record<string, unknown> = Record<string, never>,
> = Omit<ILoggerCore<TMode, TShared>, 'use' | 'unUse' | 'onDispose'> & {
  onDispose(resource: import('@migaia/plugin-host').IPluginResource): void;
};

export type ILoggerProcess = {
  readonly env: Readonly<Record<string, string | undefined>>;
  readonly stdout: { readonly isTTY?: boolean; write(value: string): unknown };
  on(event: string, listener: (...args: any[]) => void): unknown;
  removeListener(event: string, listener: (...args: any[]) => void): unknown;
  exit: (code?: number) => never;
};

export type ILoggerRuntimeManager = {
  readonly process?: ILoggerProcess;
  /** Optional Logger-owned AbortController factory for hostile-realm and cancellation tests. */ readonly createAbortController?: () => AbortController;
  randomUUID(): string;
  defer(task: () => void): void;
  write(text: string): void;
  readonly console?: {
    log(...args: unknown[]): void;
    warn(...args: unknown[]): void;
    error(...args: unknown[]): void;
  };
  fetch?: (
    input: string,
    init: {
      method: string;
      headers: Record<string, string>;
      body: string;
      signal?: AbortSignal;
    },
  ) => Promise<{
    readonly ok: boolean;
    readonly status: number;
    readonly headers: { get(name: string): string | null };
  }>;
};

export type IPipelineStage = (
  entry: ILogEntry,
  next: (entry: ILogEntry) => void,
) => void;

export type IRawEntryInput = Partial<Omit<ILogEntry, 'id'>> & {
  tag: string;
  message: string;
};

export type IShutdownReason =
  | 'signal'
  | 'uncaughtException'
  | 'unhandledRejection'
  | 'manual';

export type IStaticLoggerCtor = {
  new <
    const LocalP extends readonly ILoggerPluginConstraint[] = readonly [],
    const TMode extends IPipelineMode = 'sync',
  >(
    options: ILoggerOptions<LocalP, TMode>,
  ): Omit<ILoggerCore<TMode, IResolvedPluginShared<LocalP>>, 'config' | 'onDispose'> & {
    readonly config: ILoggerConfig;
  } & IMergePluginExts<LocalP>;
};

examples:
const log = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false },
  context: ['app', 'api'],
  topic: 'gateway',
  options: { service: 'gateway' },
  on: { before: (entry) => {} },
  pipeline: { mode: 'sync' },
  plugins: [level(), color()]
});

const audit = new Logger({ execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false }, topic: 'audit' });
audit.useSink((entry) => sendToAuditSystem(entry));

const api = new Logger({ execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false }, topic: 'api' });
api.extends(audit);

api.info('user created'); // 同时经过 api 自己的 pipeline/sink，也完整转发给 audit

import { getLoggerRuntimeManager, setLoggerRuntimeManager } from '@migaia/logger';

const previous = getLoggerRuntimeManager();
const restore = setLoggerRuntimeManager({
  randomUUID: () => crypto.randomUUID(),
  defer: (task) => queueMicrotask(task),
  write: (text) => console.log(text),
  fetch: (url, init) => fetch(url, init)
});

try {
  // 在这段作用域内创建和使用的 Logger 都会用上面这份能力
} finally {
  restore(); // 恢复到替换之前的 runtime manager
}

import { Logger } from '@migaia/logger';
import { batch, color, http, level, process, uuid } from '@migaia/logger/plugins';

const log = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false },
  context: ['worker'],
  plugins: [
    level({ level: 'info' }),
    uuid({ display: true }),
    batch({ maxSize: 50, maxWaitMs: 1000 }),
    http({ url: 'https://logs.example/v1/entries', batch: { maxSize: 50 } }),
    color({ format: 'pretty' }),
    process()
  ]
});

log.onFailure(({ source, error }) => reportLoggerFailure(source, error));
log.info('job started', { jobId: 'j_1' });
await log.flush();

import { Logger } from '@migaia/logger'
import { batch, http, level } from '@migaia/logger/plugins'

const log = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: 5_000 },
  plugins: [
    level({ level: 'info' }),
    batch({ maxSize: 50, maxWaitMs: 1_000 }),
    http({ url: 'https://logs.example/v1/entries' })
  ]
})

const stopFailureObservation = log.onFailure(({ source, error }) => {
  console.error(`[logger:${source}]`, error)
})

try {
  log.info('checkout completed: %s', 'order-42')
  await log.flush()
} finally {
  stopFailureObservation()
  await log.shutdown('manual')
}

