  /** Signal shape invalid at admission; caller must provide a structural abort signal. */ readonly invalidOption: 'INVALID_OPTION';
  /** Cooperative abort observed with primitive or undefined reason; caller should inspect cause. */ readonly aborted: 'ABORTED';
  /** Abort cleanup and abort primary both failed; caller should inspect errors in order. */ readonly abortCleanupFailed: 'ABORT_CLEANUP_FAILED';
};

