  TFeatures extends IFeatureRecord = Record<never, never>,
> = {
  readonly registerStore: (store: TStore) => void;
  readonly getStore: () => TStore;
  readonly getBackendId: () => string;
  readonly getShared: IPluginHostCore['getShared'];
  readonly features: IFeatureOutputs<TFeatures>;
  readonly featureExpose: IStorageNativeFeatureExpose<TFeatures, TStore>;
};

export type IStoragePluginId<TPlugin> = TPlugin extends {
  readonly id: infer TId extends string;
}
  ? IIsSingletonString<TId> extends true
    ? TId
    : never
  : never;

export type IStoragePluginReactiveId<TPlugin> = TPlugin extends {
  readonly id: infer TId extends string;
  readonly [storageBackendReactiveBrand]: true;
}
  ? IIsSingletonString<TId> extends true
    ? TId
    : never
  : never;

export type IStoragePluginStore<TPlugin> = TPlugin extends {
  readonly [storageBackendPluginBrand]: infer TStore extends IKeyValueStore;
}
  ? TStore
  : never;

export type IStorageReactiveFeatureMetadata<
  TStore extends IKeyValueStore = IKeyValueStore,
> = {
  readonly mode: 'push' | 'hybrid' | 'polling';
  readonly visibility: IStorageReactiveVisibility;
  readonly pollIntervalMs?: number;
  readonly subscribe?: (
    context: IStorageReactiveSubscribeContext<TStore>,
  ) => IStorageReactiveSourceDisposer | PromiseLike<unknown>;
};

export type IStorageReactiveSubscribeContext<
  TStore extends IKeyValueStore = IKeyValueStore,
> = {
  readonly store: TStore;
  /** Host-snapshotted scheduler shared with source timing and installation deadlines. */ readonly scheduler: ILifecycleScheduler;
  readonly signal: IAbortSignal;
  readonly report: (error: unknown) => void;
  /** Invalidates Resource-owned query generations after an admitted backend change. */ readonly onChange: (
    change: IStorageChange,
  ) => void;
};

export type IStorageReactiveVisibility =
  | 'instance'
  | 'document-eventual'
  | 'top-level-context-eventual'
  | 'origin-js-visible-eventual'
  | 'origin-eventual';

