export declare class StorageHostFacade<
  TStores extends Record<string, IKeyValueStore> = Record<never, never>,
  TReactiveIds extends keyof TStores & string = never,
> {
  #private;
  /** Creates the shell and snapshots lifecycle/deadline inputs before any plugin runs. */ constructor(
    options?: IStorageHostOptions,
  );
  /** Materializes one immutable plugin tuple through the canonical PluginHost batch. */ use<
    const TPlugins extends readonly IStorageBackendPluginHandle[],
  >(
    ...plugins: IRejectInstalledOrDuplicateIds<TStores, TPlugins>
  ): Promise<
    IStorageHost<
      TStores & IPluginStoreMap<TPlugins>,
      TReactiveIds | IStoragePluginReactiveId<TPlugins[number]>,
      IStoragePluginExtensions<TPlugins[number]>
    >
  >;
  /** Returns the current immutable extension plane after its corresponding batch has committed. */ get extensions(): Readonly<
    Record<PropertyKey, unknown>
  >;
  /** Looks up an exact store from the last atomically published registry snapshot. */ backend<
    TId extends keyof TStores & string,
  >(id: TId): TStores[TId];
  /** Narrows a lookup to IDs in the current immutable registry snapshot. */ hasBackend(
    id: string,
  ): id is keyof TStores & string;
  /** Returns a mutation-incapable copy of the current store registry. */ backends(): ReadonlyMap<
    keyof TStores & string,
    TStores[keyof TStores]
  >;
  /** Reports whether the committed Host registry contains an exact reactive adapter. */ hasReactiveBackend(
    id: string,
  ): id is TReactiveIds;
  /** Returns exact adapter-bound store shell and delegates query state to Resource. */ reactiveBackend<
    TId extends keyof TStores & string,
  >(id: TId): IReactiveBackendHandle<TStores[TId], TId> | undefined;
  /** Seals the facade once and delegates lifecycle cleanup to PluginHost. */ dispose(): Promise<void>;
}

