export type IAtomStore = {
  readonly runtime: IRuntime;
  readonly disposed: boolean;
  get<T>(definition: IAtomDefinition<T>): T;
  /** 非追踪读：适配层的 getSnapshot 不该在别人的捕获窗口里建边。 */ peek<T>(
    definition: IAtomDefinition<T>,
  ): T;
  /** React/concurrent speculative read; value may be discarded after the turn. */ preview<
    T,
  >(
    definition: IAtomDefinition<T>,
  ): T;
  set<T, Args extends readonly unknown[], Result>(
    definition: IWritableAtomDefinition<T, Args, Result>,
    ...args: Args
  ): Result;
  /** * 订阅一个定义。返回退订函数。 * * 这是适配层唯一需要的东西——比交出节点窄得多，实例化策略因此可以自由演进。 */ sub<
    T,
  >(
    definition: IAtomDefinition<T>,
    onChange: () => void,
  ): IDisposer;
  /** 只读派生可以路由到任意同值类型定义。 */ override<T>(
    definition: IDerivedDefinition<T>,
    replacement: IAtomDefinition<NoInfer<T>>,
  ): IDisposer;
  /** Primitive 只能替换为同一种固定 set(update) 写语义。 */ override<T>(
    definition: IPrimitiveDefinition<T> | IPrimitiveFactoryDefinition<T>,
    replacement:
      | IPrimitiveDefinition<NoInfer<T>>
      | IPrimitiveFactoryDefinition<NoInfer<T>>,
  ): IDisposer;
  /** 自定义 writable derived 必须保留完全相同的 Args/Result。 */ override<
    T,
    Args extends readonly unknown[],
    Result,
  >(
    definition: IWritableDerivedDefinition<T, Args, Result>,
    replacement: IWritableDerivedDefinition<NoInfer<T>, NoInfer<Args>, NoInfer<Result>>,
  ): IDisposer;
  /** 这个定义在本 store 内是否已有观察者。窄查询，不交出节点。 */ isObserved<T>(
    definition: IAtomDefinition<T>,
  ): boolean;
  /** * 释放单个定义的实例。 * * 与 dispose 整个 store 相对：实例式旧 API 一个实例一份定义，它 dispose 时 只该释放自己那一份，不能连累同一 store 里的其它定义。 */ release<
    T,
  >(
    definition: IAtomDefinition<T>,
  ): boolean;
  /** 已实例化的定义数量。释放行为的可观测点。 */ readonly size: number;
  dispose(): void;
};

