export type IReactiveStoreApi<S> = {
  $runtime: IRuntime;
  $async: boolean;
  $snapshot(): IStoreShape<S>;
  $subscribe(fn: () => void, options?: ISubscribeOptions): IDisposer;
  $batch(recipe: (draft: IStoreShape<S>) => void): void;
  $set(patch: IWritableStorePatch<S>): void;
  $plain(): Record<string, unknown>;
  $hydrate(partial: Record<string, unknown>, options?: IHydrateOptions): void;
  readonly $disposed: boolean;
  /** * 把外部资源挂进本 store 的所有权作用域（典型：collections）。 * * 中型场景的正确拆法是「store 持根 UI/动作，collections 承载热路径结构」； 没有 $own 时两者共 Runtime 却各管 dispose，根一释放结构节点就泄漏。 * 资源必须未归属或已归属本 Runtime；跨 Runtime 直接拒绝。 */ $own<
    T extends IDisposable,
  >(
    resource: T,
  ): T;
  /** * Always asynchronous (`docs/lifecycle/migration.sdd.md` §5.1 — the underlying * `@migaia/lifecycle` `LifecycleScope.dispose()` has no synchronous form). Resolves once every * owned Signal/Computed/Effect/wasm field has finished releasing. Callers that need "started" is * enough (fire React `useEffect` cleanup, tear down a request scope) may call this without * awaiting; `$disposed` already flips to `true` synchronously before any owned resource is * touched, so read-path guards observe the disposed state immediately regardless of whether the * caller awaits. */ $dispose(): Promise<void>;
};

