import { bindStoreMiddleware, ClonePolicy } from '@migaia/store-middleware';

// 默认 clone 是 ClonePolicy.diagnostic（尽力而为、逐层深拷贝）；
// 状态树很大或事件很密集时，改成零拷贝的 opaque 换取性能，
