    readonly value: number;
    readonly version: bigint;
  };
  /** 写某一格；返回新版本，或 undefined 表示没写（值未变或期望值不符）。 */ writeCell(
    index: number,
    value: number,
    expected?: number,
  ): bigint | undefined;
