type IWebRpcFactoryConfig<TTargetId extends string = string> = {
  readonly id: string // 必需：本端在整个通信拓扑里的唯一标识
  readonly targetIds?: readonly TTargetId[] // 已知的对端 id 列表（自动发现模式下可省略，首次 send 会懒查询）
