  readonly middlewares: readonly IWebRpcPlugin[] // 必需：必须包含且只能包含一个 connect()；其他 middleware 按需
  readonly replay?: { readonly maxEntries?: number; readonly ttlMs?: number } // 出站请求 id 的重放保护窗口容量与 TTL
